def seed_counters_from_existing_numbers(apps, schema_editor):
    """Start each series where it has already got to.

    Without this the counter begins at zero and re-issues numbers that are on
    documents customers already hold — the very thing it exists to prevent. One
    counter per financial-year prefix found in the table, set to the highest
    sequence issued in it.
    """
    Quotation = apps.get_model('inventory', 'Quotation')
    DocumentCounter = apps.get_model('inventory', 'DocumentCounter')

    highest = {}
    for number in Quotation.objects.values_list('number', flat=True):
        # 'EF/26-27/QT007' -> prefix 'EF/26-27/QT', sequence 7
        if not number or '/QT' not in number:
            continue
        prefix, _, tail = number.rpartition('QT')
        prefix += 'QT'
        if tail.isdigit():
            highest[prefix] = max(highest.get(prefix, 0), int(tail))

    for prefix, last in highest.items():
        DocumentCounter.objects.update_or_create(
            series=prefix, defaults={'last_number': last})


